    "presetByType": "{\"network_device\":{\"result\":\"部分符合\",\"record\":\"1)经核查，XXX设备使用用户名+口令方式进行身份鉴别；\\n2)经核查，用户身份标识具有唯一性。\\n3)经核查，已配置口令策略：口令长度大于8位，由字母、数字、特殊字符组成，但未配置口令定期更换策略。\\n4)经核查，用户配置信息不存在空口令用户和弱口令用户，用户名与口令不同。\\n5)经核查，在实际使用过程中，口令由字母、数字、特殊字符组成，长度大于8位，口令密文存储，但口令未定期更换。\"},\"security_device\":{\"result\":\"部分符合\",\"record\":\"1)经核查，XXX设备采用用户名+口令的方式进行登录，无相同用户名，无空口令用户，身份标识具有唯一性；2)经核查，当前口令长度大于8位，由数字、大小写字母和特殊字符组成；设置了口令策略，口令策略要求口令长度至少为8位，由数字、字母、特殊字符两种或两种以上组合，未配置口令更换周期。3)口令未定期更换。4)用户名与口令不同，口令密文存储。\"},\"server_storage\":{\"result\":\"\",\"record\":\"\"},\"management_platform\":{\"result\":\"\",\"record\":\"\"},\"business_app\":{\"result\":\"\",\"record\":\"\"},\"terminal\":{\"result\":\"符合\",\"record\":\"1)经核查，用户登录过程中，对用户进行身份鉴别，账户和口令不相同；2)经核查，不存在相同标识的用户名或UID;3)经核查，/etc/pam.d/system-auth中对口令长度、复杂度进行配置，口令长度不小于8位，口令至少包括1个数字、1个小写字母、1个大写字母、1个特殊字符；4)经核查，/etc/login.defs中进行口令更换周期的配置，密码最长有效期为90天；实际口令长度大于8位，由数据、大小写字母、特殊字符组成，口令定期更换，用户名与口令不同，口令密文存储。5)经核查，不存在空口令或弱口令。\"},\"data_resource\":{\"result\":\"不适用\",\"record\":\"根据《测评要求》测评单元中测评对象适用性描述，此类对象针对此控制项不适用。\"}}"
