    "controlPoint": "监测预警-监测",
    "controlName": "监测预警-监测",
    "requirement": "e）应采用自动化机制，对关键业务所涉及的系统的所有监测信息进行整合分析，以便及时关联资产、脆弱性、威胁等，分析关键信息基础设施的网络安全态势。关键信息基础设施跨组织、跨地域建设时，构建集中统一指挥、多点全面监测、多级联动处置的动态感知能力；",
    "minLevel": 2,
    "maxLevel": 4,
