    "domain": "security_maintenance",
    "controlPoint": "监测预警-监测",
    "controlName": "监测预警-监测",
    "requirement": "f）应将关键业务运行所涉及的各类信息进行关联，并分析整体安全态势。包括：分析不同存储库的审计日志并使之关联；将多个信息系统内多个组件的审计记录关联；将信息系统审计记录信息与物理访问监控的信息关联；将来自非技术源的信息（例如供应链信息、关键岗位人员信息等）与信息系统审计信息关联；网络安全共享信息的信息关联等；",
    "minLevel": 2,
    "maxLevel": 4,
