    "controlPoint": "监测预警-预警",
    "controlName": "监测预警-预警",
    "requirement": "a）应将监测工具设置为自动模式。当发现可能危害关键业务的迹象时，能自动报警，并自动采取相应措施，降低关键业务被影响的可能性。例如：恶意代码防御机制、入侵检测设备或者防火墙等弹出对话框、发出声音或者向相关人员发出电子邮件等方式进行报警；",
