    "domain": "security_maintenance",
    "controlPoint": "监测预警-预警",
    "controlName": "监测预警-预警",
    "requirement": "c）应能持续获取预警发布机构的安全预警信息，分析、研判相关事件或威胁对自身网络安全保护对象可能造成损害的程度，必要时启动应急预案。获取的安全预警信息应按照规定通报给相关人员和相关部门；",
